/** Lookup by exact 6-digit code. */
export const NAICS_BY_CODE: Record<string, NaicsIndustry> = Object.fromEntries(
  NAICS_INDUSTRIES.map((n) => [n.code, n])
);

/** Lookup by exact (case-insensitive) canonical title. */
const NAICS_BY_TITLE: Record<string, NaicsIndustry> = Object.fromEntries(
  NAICS_INDUSTRIES.map((n) => [n.title.toLowerCase(), n])
);

/** Resolve a stored industry value (title, code, or "code - title") to its entry. */
export function resolveNaics(value: string | null | undefined): NaicsIndustry | undefined {
  if (!value) return undefined;
  const v = value.trim();
  if (NAICS_BY_CODE[v]) return NAICS_BY_CODE[v];
  const codeMatch = v.match(/^(\d{6})\b/);
  if (codeMatch && NAICS_BY_CODE[codeMatch[1]]) return NAICS_BY_CODE[codeMatch[1]];
  return NAICS_BY_TITLE[v.toLowerCase()];
}

// Words too generic to help disambiguate a free-text industry.
const STOPWORDS = new Set([
  "and", "or", "the", "of", "for", "all", "other", "services", "service",
  "general", "business", "businesses", "company", "companies", "misc",
  "miscellaneous", "inc", "llc", "based", "except", "nec", "industry",
  "industries",
]);

function tokenize(s: string): string[] {
  return s
    .toLowerCase()
    .replace(/[^a-z0-9\s]/g, " ")
    .split(/\s+/)
    .filter((w) => w.length > 2 && !STOPWORDS.has(w));
}

/**
 * Best-effort map of an arbitrary free-text industry string (legacy data,
 * bank-analysis guesses) to the closest NAICS entry. Returns undefined when
 * nothing clears a confidence floor, so callers can flag for manual review
 * rather than silently mis-classify.
 */
export function matchNaics(input: string | null | undefined): NaicsIndustry | undefined {
  const exact = resolveNaics(input);
  if (exact) return exact;
  const tokens = tokenize(input ?? "");
  if (tokens.length === 0) return undefined;
  let best: NaicsIndustry | undefined;
  let bestScore = 0;
  for (const n of NAICS_INDUSTRIES) {
    const hay = (n.title + " " + n.sectorTitle).toLowerCase();
    let score = 0;
    for (const t of tokens) if (hay.includes(t)) score += t.length;
    if (score > bestScore) {
      bestScore = score;
      best = n;
    }
  }
  // Require a meaningful token to have landed (>=4 chars of overlap).
  return bestScore >= 4 ? best : undefined;
}
